package com.order.order_service.controller;
import com.order.order_service.service.AdminReportService;import java.time.LocalDate;import java.util.Map;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/admin/reports")public class AdminReportController{private final AdminReportService service;public AdminReportController(AdminReportService s){service=s;}@GetMapping("/summary")public Map<String,Object> summary(@AuthenticationPrincipal Jwt jwt,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){if(!"ROLE_ADMIN".equals(jwt.getClaimAsString("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator role is required");try{return service.summary(from,to);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage(),e);}}}
